public static long maxOperationsOnGraph(int N, int M, int[] u, int[] v, int[] W, long[] A) {
    long operations = 0;
    boolean hasPieces = true;

    while (hasPieces) {
        hasPieces = false;
        for (int i = 0; i < N; i++) {
            if (A[i] > 0) {
                hasPieces = true;
                A[i]--;
                int weightX = W[i];
                for (int j = 0; j < M; j++) {
                    if (u[j] == i || v[j] == i) {
                        int neighbor = (u[j] == i) ? v[j] : u[j];
                        if (W[neighbor] < weightX) {
                            A[neighbor]++;
                        }
                    }
                }
                operations++;
                break;
            }
        }
    }

    return operations;
}
